Definition saved (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M (S - 8) (sv 1) /\ L5.u64_at RSEGS M (S - 16) (sv 8) /\ L5.u64_at RSEGS M (S - 24) (sv 9)
  /\ L5.u64_at RSEGS M (S - 32) (sv 18) /\ L5.u64_at RSEGS M (S - 40) (sv 19) /\ L5.u64_at RSEGS M (S - 48) (sv 20) /\ L5.u64_at RSEGS M (S - 56) (sv 21)
  /\ L5.u64_at RSEGS M (S - 64) (sv 22) /\ L5.u64_at RSEGS M (S - 72) (sv 23) /\ L5.u64_at RSEGS M (S - 80) (sv 24) /\ L5.u64_at RSEGS M (S - 88) (sv 25).
(* [comment removed for export] *)
Definition kept0 (R : bvmap 5 word) : Prop := forall k, In k [3; 4; 26; 27]%nat -> getr R (reg k) = getr R0 (reg k).
(* [comment removed for export] *)
Definition lregs (R : bvmap 5 word) : Prop :=
  getr R (reg 2) = Z_to_bv 64 (S - 192) /\ getr R (reg 8) = Z_to_bv 64 ot /\ getr R (reg 9) = Z_to_bv 64 o /\ getr R (reg 18) = Z_to_bv 64 (S - 136)
  /\ getr R (reg 19) = Z_to_bv 64 10 /\ getr R (reg 20) = Z_to_bv 64 MAGIC /\ getr R (reg 21) = Z_to_bv 64 18 /\ kept0 R.
(* [comment removed for export] *)
Definition mem_ok (M : word -> option byte) : Prop :=
  PMK.ek L LB S PQTSS.WRS_SCR [(ot, 24)] M0 M /\ PMK.dk L LB S PQTSS.WRS_SCR M0 M /\ L5C.stk (hl_sptop L) M S PQTSS.WRS_SCR /\ L5.img_clear M 65536 814272.
(* [comment removed for export] *)
Definition thisc (M : word -> option byte) : Prop :=
  L5.u8_at RSEGS M o fb /\ L5.u64_at RSEGS M (o + 8) (Z.of_nat len) /\ L5.u64_at RSEGS M (o + 16) v0 /\ L5.u64_at RSEGS M (o + 24) 0.
(* [comment removed for export] *)
Definition post (M1 : word -> option byte) (model1 : Model) (x' : PM.vstr) (cr1 : credit) : Prop :=
  PM.vstr_at RSEGS PMSP.T3 M1 ot x' /\ 1 <= PM.vs_size x' <= 21 /\ PQTSS.ts_text M1 ot x' /\ PQTSS.ws1_post L LB M1 len x x' cr0 cr1
  /\ model_but_vm model0 model1 /\ hi_heap HI (PM.vs_own x' ++ LB) cr1 M1 (m_vmmaps model1).

