Lemma fin (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (x' : PM.vstr) (cr1 : credit) (b rb : Z) :
  lregs R1 -> L5.u8_at RSEGS M1 (S - 184) 0 -> L5.u8_at RSEGS M1 (S - 152) rb -> L5.u8_at RSEGS M1 (S - 120) b -> 0 <= b < 256 -> Z.testbit b 0 = false ->
  0 <= rb < 256 -> Z.testbit rb 0 = false ->
  saved M1 -> mem_ok M1 -> post M1 model1 x' cr1 ->
