(* [comment removed for export] *)
Definition ccls (b : Z) : Prop := b = 45 \/ 48 <= b <= 57.
Definition strC (M : word -> option byte) (q n : Z) : Prop := forall i, 0 <= i < n -> exists b, L5.u8_at RSEGS M (q + i) b /\ ccls b.
