Definition xpost (c q : Z) (cr1 : credit) : Prop :=
  match x with
  | PM.VShort _ => c = 26 /\ cr1 = debit L cr0 26 /\ block_range L q 26 /\ blocks_apart q 26 LB
  | PM.VLong c0 _ p0 => c = c0 /\ q = p0 /\ cr1 = cr0
  end.
Definition ctx (M : word -> option byte) (model1 : Model) (cr1 : credit) (c q : Z) : Prop :=
  mem_ok M /\ saved M /\ thisc M /\ model_but_vm model0 model1 /\ hi_heap HI ((q, c) :: LB) cr1 M (m_vmmaps model1) /\ xpost c q cr1.
(* [comment removed for export] *)
Definition tcells (M : word -> option byte) (b rb : Z) : Prop :=
  L5.u8_at RSEGS M (S - 184) 0 /\ L5.u8_at RSEGS M (S - 152) rb /\ L5.u8_at RSEGS M (S - 120) b /\ 0 <= b < 256 /\ Z.testbit b 0 = false
  /\ 0 <= rb < 256 /\ Z.testbit rb 0 = false.

