Local Ltac wsfeed := first [ PMK.sc | unfold PQTSWP.aligned, PQTSDP.aligned; first [assumption | lia] ].
Local Ltac splits H := lazymatch type of H with _ /\ _ => let H1 := fresh "Cj" in let H2 := fresh "Cj" in destruct H as [H1 H2]; splits H1; splits H2 | _ => idtac end.

(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma revL (k : nat) : forall (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (cr1 : credit) (c q n b rb lo hi : Z),
  hi - lo <= Z.of_nat k ->
  lregs R1 -> getr R1 (reg 10) = Z_to_bv 64 (lo + 1) -> getr R1 (reg 11) = Z_to_bv 64 hi -> q <= lo -> lo < hi -> hi <= q + n - 1 ->
  strL M1 c q n -> strC M1 q n -> 1 <= n <= 21 -> ctx M1 model1 cr1 c q -> tcells M1 b rb -> len = 1%nat ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x46dd8 M1 model1) K.
Proof.
