(* [comment removed for export] *)
Lemma loopB (k : nat) : forall (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (cr1 : credit) (c q b rb j rr rlen r0 : Z),
  18 - j <= Z.of_nat k ->
  lregs R1 -> getr R1 (reg 10) = Z_to_bv 64 j -> getr R1 (reg 22) = Z_to_bv 64 rr -> getr R1 (reg 23) = Z_to_bv 64 1 -> getr R1 (reg 24) = Z_to_bv 64 (-1) ->
  0 <= j <= 18 -> 0 <= rr < 2 ^ 64 ->
  strL M1 c q j -> strC M1 q j -> ctx M1 model1 cr1 c q -> tcells M1 b rb -> dcells M1 rlen r0 -> len = 1%nat ->
  (forall (fx2 : FPState) (R2 : bvmap 5 word) (M2 : word -> option byte),
      lregs R2 -> getr R2 (reg 1) = Z_to_bv 64 0x46d04 -> getr R2 (reg 10) = Z_to_bv 64 (S - 120) -> getr R2 (reg 11) = Z_to_bv 64 (S - 184) ->
      getr R2 (reg 12) = Z_to_bv 64 (S - 120) -> getr R2 (reg 13) = Z_to_bv 64 (S - 152) -> getr R2 (reg 14) = Z_to_bv 64 1 ->
      strL M2 c q 19 -> strC M2 q 19 -> ctx M2 model1 cr1 c q -> tcells M2 b rb -> dcells M2 rlen r0 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 0x42450 M2 model1) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x46d38 M1 model1) K.
