(* [comment removed for export] *)
Lemma carryD M M1 (P : Z -> Prop) model1 cr1 c q :
  ctx M model1 cr1 c q -> mem_grows M M1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ P a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
  (forall a, P a -> (S - 9216 <= a < S - 192) \/ (S - 184 <= a < S - 88)) ->
  26 <= c -> 4096 <= q -> q + c <= hl_ceil L ->
  hi_heap HI ((q, c) :: LB) cr1 M1 (m_vmmaps model1) ->
